-- ============================================================================
-- 069: 修正 pt_builtin_openai_responses 的 params/response_params 落库形状
--
-- 背景（B-002）：068 的 INSERT 把 params/response_params 写成 '{}'（空对象），
-- 而契约要求 JSON 数组 ⇒ 前端 serverTemplateToLocal 的 (t.params ?? []).map 抛错，
-- syncCatalog 降级离线缓存，页面无法展示新增模板。
-- 依据：protocol-gen 从官方 openapi.json（v2.3.0）确定性生成 32 个 params + 37 个响应映射；
--       required 按官方语义仅 model 由执行器注入（role=model），不臆测（061/064 铁律）。
-- 幂等：UPDATE 仅作用于本模板，重复执行结果一致。
-- ============================================================================

UPDATE protocol_templates SET
    params = $$[{"key": "metadata", "type": "object", "required": false}, {"key": "prompt_cache_key", "type": "object", "required": false}, {"key": "prompt_cache_retention", "type": "object", "required": false}, {"key": "safety_identifier", "type": "object", "required": false}, {"key": "temperature", "type": "object", "required": false}, {"key": "top_logprobs", "type": "object", "required": false}, {"key": "top_p", "type": "object", "required": false}, {"key": "user", "type": "object", "required": false, "desc": "This field is being replaced by `safety_identifier` and `prompt_cache_key`. Use `prompt_cache_key` instead to maintain caching optimizations.\nA stable identifier for your end-users.\nUsed to boost cache hit rates by better bucketing similar requests and  to help OpenAI detect and prevent abuse. [Learn more](https://developers.openai.com/api/docs/guides/safety-best-practices#implement-safety-identifiers).\n"}, {"key": "prompt_cache_options", "type": "object", "required": false}, {"key": "background", "type": "object", "required": false}, {"key": "max_tool_calls", "type": "object", "required": false}, {"key": "model", "type": "object", "required": false, "desc": "Model ID used to generate the response, like `gpt-6-astra`. OpenAI\noffers a wide range of models with different capabilities, performance\ncharacteristics, and price points. Refer to the [model guide](https://developers.openai.com/api/docs/models)\nto browse and compare available models.\n", "role": "model"}, {"key": "previous_response_id", "type": "object", "required": false}, {"key": "prompt", "type": "object", "required": false}, {"key": "text", "type": "object", "required": false}, {"key": "tool_choice", "type": "object", "required": false}, {"key": "tools", "type": "object", "required": false}, {"key": "access_programs", "type": "object", "required": false}, {"key": "context_management", "type": "object", "required": false}, {"key": "conversation", "type": "object", "required": false}, {"key": "include", "type": "object", "required": false}, {"key": "input", "type": "object", "required": false}, {"key": "instructions", "type": "object", "required": false}, {"key": "max_output_tokens", "type": "object", "required": false}, {"key": "moderation", "type": "object", "required": false}, {"key": "parallel_tool_calls", "type": "object", "required": false}, {"key": "reasoning", "type": "object", "required": false}, {"key": "service_tier", "type": "object", "required": false}, {"key": "store", "type": "object", "required": false}, {"key": "stream", "type": "object", "required": false}, {"key": "stream_options", "type": "object", "required": false}, {"key": "truncation", "type": "object", "required": false}]$$::jsonb,
    response_params = $$[{"key": "metadata", "type": "object"}, {"key": "prompt_cache_key", "type": "object"}, {"key": "prompt_cache_retention", "type": "object"}, {"key": "safety_identifier", "type": "object"}, {"key": "temperature", "type": "object"}, {"key": "top_logprobs", "type": "object"}, {"key": "top_p", "type": "object"}, {"key": "user", "type": "object", "value": "This field is being replaced by `safety_identifier` and `prompt_cache_key`. Use `prompt_cache_key` instead to maintain caching optimizations.\nA stable identifier for your end-users.\nUsed to boost cache hit rates by better bucketing similar requests and  to help OpenAI detect and prevent abuse. [Learn more](https://developers.openai.com/api/docs/guides/safety-best-practices#implement-safety-identifiers).\n"}, {"key": "background", "type": "object"}, {"key": "max_tool_calls", "type": "object"}, {"key": "model", "type": "object", "value": "Model ID used to generate the response, like `gpt-6-astra`. OpenAI\noffers a wide range of models with different capabilities, performance\ncharacteristics, and price points. Refer to the [model guide](https://developers.openai.com/api/docs/models)\nto browse and compare available models.\n"}, {"key": "previous_response_id", "type": "object"}, {"key": "prompt", "type": "object"}, {"key": "text", "type": "object"}, {"key": "tool_choice", "type": "object"}, {"key": "tools", "type": "object"}, {"key": "access_programs", "type": "object"}, {"key": "completed_at", "type": "object"}, {"key": "conversation", "type": "object"}, {"key": "created_at", "type": "number", "value": "Unix timestamp (in seconds) of when this Response was created.\n"}, {"key": "error", "type": "object"}, {"key": "id", "type": "string", "value": "Unique identifier for this Response.\n"}, {"key": "incomplete_details", "type": "object"}, {"key": "instructions", "type": "object"}, {"key": "max_output_tokens", "type": "object"}, {"key": "moderation", "type": "object"}, {"key": "object", "type": "string", "value": "The object type of this resource - always set to `response`.\n"}, {"key": "output_text", "type": "object"}, {"key": "parallel_tool_calls", "type": "boolean", "value": "Whether to allow the model to run tool calls in parallel.\n"}, {"key": "prompt_cache_diagnostics", "type": "object"}, {"key": "prompt_cache_options", "type": "object"}, {"key": "reasoning", "type": "object"}, {"key": "service_tier", "type": "object"}, {"key": "status", "type": "string", "value": "The status of the response generation. One of `completed`, `failed`,\n`in_progress`, `cancelled`, `queued`, or `incomplete`.\n"}, {"key": "truncation", "type": "object"}, {"key": "usage", "type": "object"}, {"key": "output.0.", "type": "object"}]$$::jsonb
WHERE id = 'pt_builtin_openai_responses';
